import{_ as t,o as a,c as r,a0 as o}from"./chunks/framework.DoRPXVp_.js";const u=JSON.parse('{"title":"ADR-0004: LRP Per-Peer Authentication via X25519 Challenge-Response","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0004-lrp-per-peer-authentication.md","filePath":"adr/0004-lrp-per-peer-authentication.md"}'),i={name:"adr/0004-lrp-per-peer-authentication.md"};function n(l,e,s,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0004-lrp-per-peer-authentication-via-x25519-challenge-response" tabindex="-1">ADR-0004: LRP Per-Peer Authentication via X25519 Challenge-Response <a class="header-anchor" href="#adr-0004-lrp-per-peer-authentication-via-x25519-challenge-response" aria-label="Permalink to &quot;ADR-0004: LRP Per-Peer Authentication via X25519 Challenge-Response&quot;">​</a></h1><ul><li><strong>Status</strong>: Proposed</li><li><strong>Date</strong>: 2026-09-17</li><li><strong>Related</strong>: ADR-0003 (enrollment approval + client-side keygen — control plane), 2026-09-17 codebase review findings #1-#5</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The LRP relay previously accepted any <code>Register</code> frame and let the client claim any peer ID. Commit <code>a6e75b94</code> added a <strong>shared token</strong> so at least deployment membership is required, but a shared token proves <em>membership</em>, not <em>identity</em>: every peer in the deployment holds the same secret, so any valid member can still register as any other member&#39;s peer ID and</p><ul><li>receive the victim&#39;s relayed traffic (encrypted, but usable for traffic analysis and replay-into-WireGuard noise),</li><li>inject garbage frames into the victim&#39;s WireGuard receive path,</li><li>blackhole the victim&#39;s relay connectivity (the only fallback when ICE fails, e.g. symmetric NAT on both sides).</li></ul><p>Constraints that shape the solution:</p><ul><li>The relay (<code>lrper</code>) is a <strong>standalone</strong> process. It has no access to the control plane&#39;s peer registry and should stay that way (it is deployed independently and must keep working when the control plane is down).</li><li>The system already has a <strong>self-certifying identity</strong>: <code>PeerID</code> is the first 8 bytes (big-endian) of the peer&#39;s WireGuard public key (<code>infra.FromKey</code>). LRP session IDs, NATS subjects and fake endpoint addresses are all derived from it.</li><li>WireGuard keys are X25519 (Curve25519) pairs — <strong>not signing keys</strong> — so &quot;sign the register request&quot; is not directly available.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Bind a relay session to possession of the peer&#39;s WireGuard private key with an <strong>ephemeral X25519 challenge-response performed at Register time</strong>:</p><ol><li>Client sends <code>Register { claimed PeerID, client public key (32 B), shared token if configured }</code>.</li><li>Relay checks <code>first-8-bytes(client public key) == claimed PeerID</code>, then replies with <code>AuthChallenge { 32 B ephemeral X25519 public key }</code>, generated fresh for this connection (its private half never leaves memory and is discarded after verification).</li><li>Client responds <code>AuthResponse { X25519(client private key, relay ephemeral public key) }</code> (32 B).</li><li>Relay computes <code>X25519(relay ephemeral private key, client public key)</code> and accepts the session only on an exact match (constant-time compare, reject the all-zero shared secret).</li></ol><p>The claimed ID ↔ public key prefix check plus the DH proof together make impersonation impossible without the victim&#39;s private key: a forged public key with the right 8-byte prefix fails step 4, and a real key of another peer fails the prefix check.</p><p><strong>The relay needs no control-plane contact and no new secrets.</strong> This works identically for standalone <code>lrper</code>, the <code>manager lrper</code> subcommand and the all-in-one binary.</p><h2 id="detailed-design" tabindex="-1">Detailed design <a class="header-anchor" href="#detailed-design" aria-label="Permalink to &quot;Detailed design&quot;">​</a></h2><h3 id="wire-protocol" tabindex="-1">Wire protocol <a class="header-anchor" href="#wire-protocol" aria-label="Permalink to &quot;Wire protocol&quot;">​</a></h3><p>New frame commands on the control channel (TCP: the upgraded stream; QUIC: the control stream):</p><table tabindex="0"><thead><tr><th>Cmd</th><th>Value</th><th>Direction</th><th>Payload</th></tr></thead><tbody><tr><td><code>AuthChallenge</code></td><td>0x05</td><td>relay → client</td><td>32 B ephemeral X25519 public key</td></tr><tr><td><code>AuthResponse</code></td><td>0x06</td><td>client → relay</td><td>32 B shared secret (<code>DH(priv, challenge)</code>)</td></tr></tbody></table><p><code>Register</code> payload becomes <code>token (0..512 B) || client public key (32 B)</code>. The session is inserted into the <code>SessionManager</code> <strong>only after</strong> step 4 succeeds — a half-registered connection must never occupy or replace an ID slot (this also removes the current last-write-wins hijack window for unauthenticated connects). On any failure the relay closes the connection; no error frames (do not help attackers probe).</p><h3 id="crypto-notes" tabindex="-1">Crypto notes <a class="header-anchor" href="#crypto-notes" aria-label="Permalink to &quot;Crypto notes&quot;">​</a></h3><ul><li>Use <code>golang.org/x/crypto/curve25519.X25519()</code> for both sides.</li><li>Reject an all-zero DH output (low-order point input); log and close.</li><li>The ephemeral keypair is generated with <code>crypto/rand</code> per connection and zeroed after use; replay is structurally impossible because the challenge never repeats.</li><li><code>Forward</code>/<code>Probe</code> frames from a connection are ignored until the session is fully registered.</li></ul><h3 id="compatibility-and-rollout" tabindex="-1">Compatibility and rollout <a class="header-anchor" href="#compatibility-and-rollout" aria-label="Permalink to &quot;Compatibility and rollout&quot;">​</a></h3><p>Same staged pattern as the shared-token change:</p><ol><li>Ship relay support behind <code>--require-peer-auth</code> (default <strong>off</strong>): with the flag off, the relay performs the handshake when the client offers it but still accepts legacy <code>Register</code>-only connections.</li><li>Ship client support (agent + sandbox paths): clients always perform the handshake; if the relay answers a legacy bare-register instead of challenging, the client proceeds (server is older).</li><li>Operators who want the guarantee flip <code>--require-peer-auth</code>; from then on, unauthenticated registers are rejected with a clear server log line.</li></ol><p>No auto-fallback beyond the above: mixed-version clusters degrade to membership-only auth (today&#39;s behavior) rather than failing.</p><h3 id="testing-plan" tabindex="-1">Testing plan <a class="header-anchor" href="#testing-plan" aria-label="Permalink to &quot;Testing plan&quot;">​</a></h3><ul><li>Unit: DH proof happy path; forged public key with correct prefix; wrong prefix with valid DH; all-zero shared secret; replayed response against a second connection; <code>token || pubkey</code> payload parsing.</li><li>Integration: real relay on TCP loopback — two clients, one attempts to register the other&#39;s ID with its own key → rejected; victim&#39;s session unaffected.</li><li>Race: <code>-race</code> on the session manager insertion point (only-after-success registration changes the locking window).</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong>Control-plane-issued per-peer HMAC credentials</strong> (server signs <code>HMAC(relaySecret, peerID, expiry)</code> at registration, relay verifies locally): single-round-trip and cheap to verify, but requires distributing <code>relaySecret</code> to every standalone relay deployment and threading the credential through registration + netmap + re-registration. The X25519 design needs zero credential infrastructure and composes with ADR-0003 (proof of the actual identity key, not a bearer credential derived from it).</li><li><strong>Relay → control-plane validation callback</strong>: adds a runtime dependency from the fallback data path to the control plane; a relay must stay usable during control-plane outages. Rejected.</li><li><strong>WireGuard-noise-style full handshake on the relay channel</strong>: strictly more security (relay traffic would become encrypted against off-relay observers) but a much larger protocol change; the relay already carries only WireGuard-encrypted payloads, so hop encryption adds little.</li></ul><h2 id="security-analysis" tabindex="-1">Security analysis <a class="header-anchor" href="#security-analysis" aria-label="Permalink to &quot;Security analysis&quot;">​</a></h2><p><strong>Closes</strong>: cross-member session hijack, ID squatting, unauthenticated relay use (combined with the existing token), registration-based DoS of a specific victim ID.</p><p><strong>Remains open</strong> (documented non-goals for this ADR):</p><ul><li>The relay still observes ciphertext metadata (who talks to the relay, when, volume). Mitigating this means hopping relays / cover traffic — out of scope.</li><li>QUIC relay transport uses <code>InsecureSkipVerify</code>; a MITM on the relay leg can strip traffic. Fix: control plane advertises the relay certificate fingerprint (TOFU pinning) — small follow-up ADR.</li><li>A <em>valid</em> member can still flood the relay (internal DoS). Mitigation: per-session rate limits — future work.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Registration gains one extra round trip per relay connection (negligible; it happens once per connection lifetime, and the auto-reconnect supervisor from commit <code>92d4dca4</code> is the only caller).</li><li>Relay and agent must both understand the handshake before the flag can be enabled (documented upgrade order above).</li><li>With ADR-0003 landed, the relay proves possession of a key the control plane never saw — the identity chain becomes end-to-end: client-generated key → approved peer → self-certifying relay session.</li></ul>',33)])])}const y=t(i,[["render",n]]);export{u as __pageData,y as default};
